    fn split_single_operator_prefix_recognizes_all_operators() {
        assert_eq!(split_single_operator_prefix("^1.2.3"), Some(("^", "1.2.3")));
        assert_eq!(split_single_operator_prefix("~1.2.3"), Some(("~", "1.2.3")));
        assert_eq!(split_single_operator_prefix(">=1.2.3"), Some((">=", "1.2.3")));
        assert_eq!(split_single_operator_prefix(">1.2.3"), Some((">", "1.2.3")));
        assert_eq!(split_single_operator_prefix("<=1.2.3"), Some(("<=", "1.2.3")));
