166	            let root_manifest = self.inheritance.as_ref().ok_or_else(not_found)?.root_manifest.clone();
167	            let root_cargo = self.workspace_root.join(&root_manifest);
168	            if self.absolute == root_cargo {
169	                return Err(ManifestError::InvariantViolation {
170	                    path: self.path.clone(),
171	                    message: format!(
172	                        "dependency `{name}` is workspace-inherited but this manifest IS the workspace root (`{}`); refusing to delegate to avoid overwriting the just-written root manifest with a stale in-memory document",
173	                        root_cargo.display()
174	                    ),
175	                });
176	            }
177	            let mut ws_res = WorkspaceCargoResolver::load_at(&self.workspace_root, &root_manifest)?;
178	            ws_res.write_dependency(name, new, permit)?;
179	            return ws_res.persist(permit);
180	        }
181	
182	        let item = dependency_table_mut(&mut self.document, section, target)
183	            .and_then(|table| table.get_mut(name))
184	            .ok_or_else(not_found)?;
185	        set_dependency_version(item, new.render()).map_err(|()| ManifestError::UnrecognizedDependencyValue {
186	            path: self.path.clone(),
187	            name: name.to_string(),
188	        })
189	    }
