192	        &mut self,
193	        _updates: &[(String, Version)],
194	        _permit: &ApplyPermit,
195	    ) -> Result<(), ManifestError> {
196	        Err(ManifestError::UnsupportedOperation {
197	            path: self.path.clone(),
198	            format: ManifestFormat::CargoToml,
199	            operation: "update_optional_dependencies",
200	        })
201	    }
