219	/// Every dependency table a manifest can declare: the top-level ones, then the same three
220	/// under each `[target.<cfg>]` key. Owned, so callers can mutate the document while iterating.
221	fn dependency_locations(doc: &toml_edit::DocumentMut) -> Vec<(&'static str, DepKind, Option<String>)> {
222	    let mut locations: Vec<_> = DEPENDENCY_SECTIONS
223	        .iter()
224	        .map(|(section, kind)| (*section, *kind, None))
225	        .collect();
226	    if let Some(targets) = doc.get("target").and_then(|item| item.as_table_like()) {
227	        for (cfg, _) in targets.iter() {
228	            for (section, kind) in DEPENDENCY_SECTIONS {
229	                locations.push((section, kind, Some(cfg.to_string())));
230	            }
231	        }
232	    }
233	    locations
