277	fn parse_cargo_dep_item(item: &toml_edit::Item, kind: &mut DepKind) -> DepSpec {
278	    if let Some(table) = item.as_inline_table() {
279	        if table.get("optional").and_then(|o| o.as_bool()) == Some(true) {
280	            *kind = DepKind::Optional;
281	        }
282	        if let Some(v_str) = table.get("version").and_then(|v| v.as_str()) {
283	            return parse_cargo_spec_str(v_str);
284	        }
285	    } else if let Some(table) = item.as_table() {
286	        if table.get("optional").and_then(|o| o.as_bool()) == Some(true) {
287	            *kind = DepKind::Optional;
288	        }
289	        if let Some(v_str) = table.get("version").and_then(|v| v.as_str()) {
290	            return parse_cargo_spec_str(v_str);
291	        }
292	    } else if let Some(v_str) = item.as_str() {
293	        return parse_cargo_spec_str(v_str);
294	    }
295	
296	    DepSpec::Opaque(item.to_string().trim().to_string())
297	}
