299	fn parse_cargo_spec_str(s: &str) -> DepSpec {
300	    if crate::common::is_bare_semver(s)
301	        && let Ok(v) = Version::parse(s, VersionGrammar::SemVer)
302	    {
303	        return DepSpec::CargoBare(v);
304	    }
305	    if let Ok(req) = VersionReq::parse(s, Ecosystem::Cargo) {
306	        return DepSpec::Range(req, s.to_string());
307	    }
308	    DepSpec::Opaque(s.to_string())
309	}
310	
311	pub fn round_trip(spec: &DepSpec, target: &Version) -> Option<DepSpec> {
312	    match spec {
313	        DepSpec::CargoBare(_) => Some(DepSpec::CargoBare(target.clone())),
314	        DepSpec::Range(_, original) => {
315	            if original.contains(',') {
316	                let parts: Vec<&str> = original.split(',').collect();
317	                let mut rewritten_parts = Vec::new();
318	                for part in parts {
319	                    let part_trimmed = part.trim();
320	                    let (prefix, rest) = crate::common::split_single_operator_prefix(part_trimmed)?;
321	                    if prefix.starts_with('>')
322	                        || prefix.starts_with('=')
323	                        || prefix.starts_with('^')
324	                        || prefix.starts_with('~')
325	                    {
326	                        let rendered = format!("{prefix}{}", render_at_precision(target, rest));
327	                        rewritten_parts.push(rendered);
328	                    } else if prefix.starts_with('<') {
329	                        // Upper-bound clauses are never rewritten (the clause text
330	                        // is preserved verbatim), but we must still check whether
331	                        // the target actually falls within it. If it doesn't, the
332	                        // rewrite would silently produce an impossible constraint
333	                        // (e.g. ">=2.1.0, <2.0.0"), so decline with None. If it
334	                        // does, the upper bound clause is passed through unchanged.
335	                        let bound = Version::parse(rest, target.grammar()).ok()?;
336	                        let ordering = target.partial_compare(&bound)?;
337	                        let exceeds_bound = if prefix == "<=" {
338	                            ordering == std::cmp::Ordering::Greater
339	                        } else {
340	                            ordering != std::cmp::Ordering::Less
341	                        };
342	                        if exceeds_bound {
343	                            return None;
344	                        }
345	                        rewritten_parts.push(part_trimmed.to_string());
346	                    } else {
347	                        rewritten_parts.push(part_trimmed.to_string());
348	                    }
349	                }
350	                let rendered = rewritten_parts.join(", ");
351	                let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
352	                return Some(DepSpec::Range(req, rendered));
353	            }
354	            let (prefix, rest) = crate::common::split_single_operator_prefix(original)?;
355	            if rest.contains('*') {
356	                return None;
357	            }
358	            let rendered = format!("{prefix}{}", render_at_precision(target, rest));
359	            let req = VersionReq::parse(&rendered, Ecosystem::Cargo).ok()?;
360	            Some(DepSpec::Range(req, rendered))
361	        }
362	        _ => None,
363	    }
364	}
365	
366	fn render_at_precision(target: &Version, original_clause: &str) -> String {
367	    if original_clause.contains('-') || target.is_prerelease() {
368	        return target.render().to_string();
369	    }
370	    let parts: Vec<&str> = original_clause.split('.').collect();
371	    let maj = target.major().unwrap_or(0);
372	    let min = target.minor().unwrap_or(0);
373	    let pat = target.patch().unwrap_or(0);
374	
375	    match parts.len() {
376	        1 => format!("{maj}"),
377	        2 => format!("{maj}.{min}"),
378	        _ => format!("{maj}.{min}.{pat}"),
379	    }
380	}
