413	impl WorkspaceCargoResolver {
414	    /// Loads the Cargo workspace root manifest at `workspace_root/root_manifest`, keeping `root_manifest` (relative to
415	    /// `workspace_root`) as the path every report, diff and staged file names it by.
416	    pub fn load_at(workspace_root: &Path, root_manifest: &Path) -> Result<Self, ManifestError> {
417	        let rel_path = workspace_relative(root_manifest).map_err(|e| ManifestError::Read {
418	            path: root_manifest.to_path_buf(),
419	            message: e.to_string(),
420	        })?;
421	        let absolute_path = workspace_root.join(&rel_path);
422	        Self::read_from(rel_path, absolute_path)
423	    }
424	
425	    pub fn load(root_manifest_path: &Path) -> Result<Self, ManifestError> {
426	        let rel_path = if root_manifest_path.is_absolute() {
427	            root_manifest_path
428	                .file_name()
429	                .map(PathBuf::from)
430	                .unwrap_or_else(|| PathBuf::from("Cargo.toml"))
431	        } else {
432	            workspace_relative(root_manifest_path).map_err(|e| ManifestError::Read {
433	                path: root_manifest_path.to_path_buf(),
434	                message: e.to_string(),
435	            })?
436	        };
437	        Self::read_from(rel_path, root_manifest_path.to_path_buf())
438	    }
439	
440	    fn read_from(rel_path: PathBuf, absolute_path: PathBuf) -> Result<Self, ManifestError> {
441	        crate::record_resolver_load_call();
442	        let content = fs::read_to_string(&absolute_path).map_err(|e| ManifestError::Read {
443	            path: rel_path.clone(),
444	            message: e.to_string(),
445	        })?;
446	
447	        let doc: toml_edit::DocumentMut = content
448	            .parse()
449	            .map_err(|e: toml_edit::TomlError| ManifestError::Parse {
450	                path: rel_path.clone(),
451	                format: ManifestFormat::CargoToml,
452	                message: e.to_string(),
453	            })?;
454	
455	        Ok(WorkspaceCargoResolver {
456	            root_path: rel_path,
457	            absolute_path,
458	            document: doc,
459	        })
460	    }
461	
462	    pub fn inheritance(&self) -> Result<WorkspaceInheritance, ManifestError> {
463	        let version = workspace_package_version(&self.document, &self.root_path)?;
464	
465	        let mut dependencies = BTreeMap::new();
466	        if let Some(table) = self
467	            .document
468	            .get("workspace")
469	            .and_then(|w| w.get("dependencies"))
470	            .and_then(|d| d.as_table_like())
471	        {
472	            for (name, item) in table.iter() {
473	                let mut kind = DepKind::Runtime;
474	                let spec = parse_cargo_dep_item(item, &mut kind);
475	                dependencies.insert(
476	                    name.to_string(),
477	                    DependencyEntry {
478	                        name: name.to_string(),
479	                        package_name: cargo_dependency_package_name(name, item).to_string(),
480	                        kind,
481	                        spec,
482	                        inherited: false,
483	                        locator: DepLocator::default(),
484	                    },
485	                );
486	            }
487	        }
488	
489	        Ok(WorkspaceInheritance {
490	            root_manifest: self.root_path.clone(),
491	            version,
492	            dependencies,
493	        })
494	    }
495	
496	    /// Returns the `[workspace.package] version` currently on disk, or `None`
497	    /// when no such field exists (e.g. the workspace does not declare a shared
498	    /// version). Used by `apply_version_plan`'s idempotency guard.
499	    pub fn workspace_version(&self) -> Result<Option<Version>, ManifestError> {
500	        workspace_package_version(&self.document, &self.root_path)
501	    }
502	
503	    /// Pure in-memory mutation of `[workspace.package] version` -- no disk
504	    /// I/O. Mirrors `CargoToml`/`PackageJson`/`PyprojectToml`'s
505	    /// `write_version`, which likewise never touches disk; callers must
506	    /// call [`Self::persist`] explicitly afterward. `_permit` is accepted
507	    /// (unused) purely for call-site symmetry with `persist`, which does
508	    /// require one.
509	    pub fn write_version(&mut self, v: &Version, _permit: &ApplyPermit) -> Result<(), ManifestError> {
510	        let ws = self
511	            .document
512	            .get_mut("workspace")
513	            .and_then(|w| w.as_table_like_mut())
514	            .ok_or_else(|| ManifestError::MissingField {
515	                path: self.root_path.clone(),
516	                field: "workspace",
517	            })?;
518	
519	        let pkg = ws
520	            .entry("package")
521	            .or_insert(toml_edit::Item::Table(toml_edit::Table::new()))
522	            .as_table_mut()
523	            .ok_or_else(|| ManifestError::MissingField {
524	                path: self.root_path.clone(),
525	                field: "workspace.package",
526	            })?;
527	
528	        crate::common::set_scalar_preserving_decor(pkg, "version", v.render());
529	        Ok(())
530	    }
531	
532	    /// Pure in-memory mutation of a `[workspace.dependencies]` entry -- no
533	    /// disk I/O. See [`Self::write_version`]'s doc for why this no longer
534	    /// persists internally; callers must call [`Self::persist`] explicitly
535	    /// afterward.
536	    pub fn write_dependency(&mut self, name: &str, new: DepSpec, _permit: &ApplyPermit) -> Result<(), ManifestError> {
537	        let ws = self
538	            .document
539	            .get_mut("workspace")
540	            .and_then(|w| w.as_table_mut())
541	            .ok_or_else(|| ManifestError::MissingField {
542	                path: self.root_path.clone(),
543	                field: "workspace",
544	            })?;
545	
546	        let deps = ws
547	            .entry("dependencies")
548	            .or_insert(toml_edit::Item::Table(toml_edit::Table::new()))
549	            .as_table_like_mut()
550	            .ok_or_else(|| ManifestError::MissingField {
551	                path: self.root_path.clone(),
552	                field: "workspace.dependencies",
553	            })?;
554	
555	        let item = deps.get_mut(name).ok_or_else(|| ManifestError::DependencyNotFound {
556	            path: self.root_path.clone(),
557	            name: name.to_string(),
558	            kind: DepKind::Runtime,
559	        })?;
560	
561	        let new_str = new.render();
562	        set_dependency_version(item, new_str).map_err(|()| ManifestError::UnrecognizedDependencyValue {
563	            path: self.root_path.clone(),
564	            name: name.to_string(),
565	        })?;
566	
567	        Ok(())
568	    }
569	
570	    /// Flushes the in-memory document to disk via
571	    /// [`crate::atomic::atomic_write`]. Distinct, explicitly-called step --
572	    /// see [`Self::write_version`]/[`Self::write_dependency`]'s docs --
573	    /// mirroring the `Manifest` trait's `persist` across `CargoToml`,
574	    /// `PackageJson`, and `PyprojectToml`.
575	    pub fn persist(&mut self, permit: &ApplyPermit) -> Result<(), ManifestError> {
576	        let text = self.document.to_string();
577	        crate::atomic::atomic_write(&self.absolute_path, &text, permit).map_err(|e| ManifestError::Write {
578	            path: self.root_path.clone(),
579	            message: e.to_string(),
580	        })?;
581	        crate::record_resolver_persist_call();
582	        Ok(())
583	    }
584	}
