588	//! Helpers shared between ecosystem-specific manifest editors (`cargo`, `npm`, `python`).
589	//!
590	//! Only functions verified to be byte-for-byte identical in behavior across
591	//! ecosystems live here. Functions that merely *look* similar but encode
592	//! ecosystem-specific semantics (e.g. `render_at_precision`, which differs
593	//! between Cargo and npm on prerelease/hyphen handling) stay local to their
594	//! respective modules.
595	
596	/// Returns true if `s` looks like a bare `major.minor.patch` semver string
597	/// (as opposed to a range expression like `^1.0.0` or `>=1.0.0`).
598	///
599	/// This is a syntactic heuristic: it does not fully validate the string as
600	/// a semver version, it just checks that it starts with an ASCII digit and
601	/// splits into exactly three dot-separated parts.
602	pub(crate) fn is_bare_semver(s: &str) -> bool {
603	    let chars = s.chars().next();
604	    if !chars.is_some_and(|c| c.is_ascii_digit()) {
605	        return false;
606	    }
607	    let parts: Vec<&str> = s.split('.').collect();
608	    parts.len() == 3
609	}
610	
611	/// Splits a version requirement clause into its leading comparison operator
612	/// (if any) and the remaining version-ish text.
613	///
614	/// Recognized operators: `^`, `~`, `>=`, `>`, `<=`, `<`, `=`. If none match,
615	/// the empty-string prefix is returned along with the trimmed input.
616	pub(crate) fn split_single_operator_prefix(s: &str) -> Option<(&str, &str)> {
617	    let trimmed = s.trim();
618	    for op in ["^", "~", ">=", ">", "<=", "<", "="] {
619	        if let Some(rest) = trimmed.strip_prefix(op) {
620	            return Some((op, rest.trim()));
621	        }
622	    }
623	    Some(("", trimmed))
624	}
625	
626	/// Sets `table[key]` to a scalar string value, preserving the existing
627	/// entry's decor (comments/whitespace) when `table[key]` is already a plain
628	/// value; otherwise inserts a fresh `key = "value"` entry with no decor to
629	/// preserve.
630	///
631	/// Takes `&mut dyn toml_edit::TableLike` rather than a concrete `Table` so
632	/// every call site can share this one implementation regardless of what
633	/// container it holds: a bare `toml_edit::Table` (Cargo's `[package]` /
634	/// `[workspace.package]` tables coerce to `&mut dyn TableLike` directly,
635	/// since `Table: TableLike`) or a `toml_edit::Item` that resolves to a
636	/// table-like value via `Item::as_table_like_mut()` (pyproject.toml's
637	/// `[project]` / `[tool.poetry]` / `[tool.flit.metadata]`, each accessed as
638	/// an `Item`, not a bare `Table`). Previously duplicated as
639	/// `cargo::set_scalar_preserving_decor` and a local closure inside
640	/// `python::PyprojectToml::write_version`.
641	pub(crate) fn set_scalar_preserving_decor(table: &mut dyn toml_edit::TableLike, key: &str, new_value: &str) {
642	    if let Some(item) = table.get_mut(key)
643	        && let Some(val) = item.as_value_mut()
644	    {
645	        let decor = val.decor().clone();
646	        let mut new_val = toml_edit::Value::from(new_value);
647	        *new_val.decor_mut() = decor;
648	        *val = new_val;
649	        return;
650	    }
651	    table.insert(key, toml_edit::value(new_value));
652	}
