654	/// A file's line-ending style: bare LF, or CRLF (common on Windows / repos
655	/// with `core.autocrlf=true`).
656	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
657	pub(crate) enum LineEnding {
658	    Lf,
659	    CrLf,
660	}
661	
662	/// Byte-level formatting facts that a CST-preserving editor must detect on
663	/// open and reapply verbatim on persist, since `toml_edit`/`serde_json`
664	/// re-serialization always produces bare-LF text with no BOM regardless of
665	/// what was originally on disk: whether the file opened with a UTF-8 BOM,
666	/// and its line-ending style.
667	///
668	/// Previously reimplemented independently -- byte-for-byte identically --
669	/// as a private `has_bom`/`line_ending` pair (plus a duplicate local
670	/// `LineEnding` enum) in both `npm::PackageJson` and
671	/// `python::PyprojectToml`, and entirely absent from `cargo::CargoToml`
672	/// (F4: a CRLF `Cargo.toml` was silently rewritten to LF on any write).
673	#[derive(Clone, Copy, Debug, PartialEq, Eq)]
674	pub(crate) struct FormatFingerprint {
675	    pub(crate) has_bom: bool,
676	    pub(crate) line_ending: LineEnding,
677	}
678	
679	impl FormatFingerprint {
680	    /// Detects BOM and line-ending style from `content`, the raw file text
681	    /// exactly as read from disk (BOM still present, if any -- this does
682	    /// its own BOM-stripping internally before checking for `"\r\n"`, so
683	    /// callers need not pre-strip).
684	    pub(crate) fn detect(content: &str) -> Self {
685	        let has_bom = content.starts_with('\u{FEFF}');
686	        let clean = content.strip_prefix('\u{FEFF}').unwrap_or(content);
687	        let line_ending = if clean.contains("\r\n") {
688	            LineEnding::CrLf
689	        } else {
690	            LineEnding::Lf
691	        };
692	        FormatFingerprint { has_bom, line_ending }
693	    }
694	
695	    /// Reapplies this fingerprint to `rendered` -- a freshly-serialized
696	    /// document body with bare-LF line endings and no BOM -- producing the
697	    /// exact text that should be written to disk.
698	    pub(crate) fn apply(&self, rendered: &str) -> String {
699	        let mut out = if self.line_ending == LineEnding::CrLf {
700	            rendered.replace("\r\n", "\n").replace('\n', "\r\n")
701	        } else {
702	            rendered.to_string()
703	        };
704	        if self.has_bom {
705	            out = format!("\u{FEFF}{out}");
706	        }
707	        out
708	    }
709	}
