use callisto_model::GroupKind;

use crate::changelog::{ChangeSource, ChangelogError, ChangelogInput};

pub fn render_section(input: &ChangelogInput) -> Result<String, ChangelogError> {
    if input.entries.is_empty() {
        return Err(ChangelogError::EmptyInput);
    }
    for entry in &input.entries {
        if entry.severity == callisto_model::Severity::None {
            return Err(ChangelogError::SeverityNoneEntry);
        }
    }

    let mut out = String::new();

    let heading = match &input.to {
        Some(v) => format!("## {}", v.render()),
        None => "## Unreleased".to_string(),
    };
    out.push_str(&heading);
    out.push('\n');
    out.push('\n');

    let mut dep_updates = Vec::new();

    for entry in &input.entries {
        match &entry.source {
            ChangeSource::Changeset { summary, .. } => {
                if summary.trim().is_empty() {
                    continue;
                }
                let indented = summary.trim_end_matches('\n');
                let indented = indented.replace('\n', "\n  ");
                out.push_str(&format!("- {indented}\n"));
            }
            ChangeSource::Commit { subject, sha } => {
                out.push_str(&format!("- {subject} ({})\n", sha.short()));
            }
            ChangeSource::DependencyUpdate { dependency, to, .. } => {
                dep_updates.push((dependency, to));
            }
            ChangeSource::PeerEscalation { dependency, to } => {
                out.push_str(&format!(
                    "- Peer dependency `{}` requires `{}`\n",
                    dependency.display_name(),
                    to.render()
                ));
            }
            ChangeSource::GroupUnion { group, kind } => {
                let k_str = match kind {
                    GroupKind::Fixed => "fixed",
                    GroupKind::Linked => "linked",
                };
                out.push_str(&format!("- Released together with the `{group}` {k_str} group.\n"));
            }
            ChangeSource::NewGroupMember { group } => {
                out.push_str(&format!("- Joined the `{group}` group at this version.\n"));
            }
        }
    }

    if !dep_updates.is_empty() {
        out.push_str("- Dependency updates\n");
        for (dep, to_ver) in dep_updates {
            out.push_str(&format!("  - `{}` → `{}`\n", dep.display_name(), to_ver.render()));
        }
    }

    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::changelog::ChangelogEntry;
    use callisto_model::{PackageId, Severity, Version, VersionGrammar};

    fn make_input(summary: &str) -> ChangelogInput {
        ChangelogInput {
            package: PackageId::parse("my-pkg").unwrap(),
            from: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            to: Some(Version::parse("1.1.0", VersionGrammar::SemVer).unwrap()),
            entries: vec![ChangelogEntry {
                severity: Severity::Patch,
                source: ChangeSource::Changeset {
                    filename: "fix.md".to_string(),
                    summary: summary.to_string(),
                },
            }],
        }
    }

    #[test]
    fn renders_basic_changelog_section() {
        let input = ChangelogInput {
            package: PackageId::parse("my-pkg").unwrap(),
            from: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            to: Some(Version::parse("1.1.0", VersionGrammar::SemVer).unwrap()),
            entries: vec![ChangelogEntry {
                severity: Severity::Minor,
                source: ChangeSource::Changeset {
                    filename: "cool-dragons.md".to_string(),
                    summary: "Add dragon feature".to_string(),
                },
            }],
        };

        let rendered = render_section(&input).unwrap();
        assert!(rendered.contains("## 1.1.0"));
        assert!(!rendered.contains("### Minor Changes"));
        assert!(!rendered.contains("### Patch Changes"));
        assert!(rendered.contains("- Add dragon feature"));
    }

    #[test]
    fn render_section_flattens_mixed_severities_into_one_list() {
        // A package released alongside a fixed group can carry entries of
        // different originally-authored severities (e.g. a patch-level fix
        // plus a group-driven minor bump). The rendered changelog must not
        // re-surface that per-entry severity distinction -- the version
        // heading already communicates the one, real applied bump.
        let input = ChangelogInput {
            package: PackageId::parse("my-pkg").unwrap(),
            from: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            to: Some(Version::parse("1.1.0", VersionGrammar::SemVer).unwrap()),
            entries: vec![
                ChangelogEntry {
                    severity: Severity::Minor,
                    source: ChangeSource::GroupUnion {
                        group: callisto_model::GroupName("workspace".to_string()),
                        kind: GroupKind::Fixed,
                    },
                },
                ChangelogEntry {
                    severity: Severity::Patch,
                    source: ChangeSource::Changeset {
                        filename: "fix.md".to_string(),
                        summary: "Fix a bug".to_string(),
                    },
                },
            ],
        };

        let rendered = render_section(&input).unwrap();
        assert!(!rendered.contains("### Major Changes"));
        assert!(!rendered.contains("### Minor Changes"));
        assert!(!rendered.contains("### Patch Changes"));
        assert!(rendered.contains("- Released together with the `workspace` fixed group."));
        assert!(rendered.contains("- Fix a bug"));
    }

    #[test]
    fn render_section_indents_multiline_summary_continuation_lines() {
        let input = make_input("First line.\n\nSecond paragraph.");
        let rendered = render_section(&input).unwrap();
        // Continuation lines must be indented — bare "\nSecond paragraph." is wrong
        assert!(
            !rendered.contains("\nSecond paragraph."),
            "continuation line must not appear unindented; got:\n{rendered}"
        );
        // Must appear with at least 2-space indent
        assert!(
            rendered.contains("\n  Second paragraph."),
            "continuation line must be indented by 2 spaces; got:\n{rendered}"
        );
    }

    #[test]
    fn render_section_handles_trailing_newline_in_summary() {
        let input = make_input("Fix bug.\n");
        let rendered = render_section(&input).unwrap();
        // A trailing newline in the summary must not produce a doubled blank line
        assert!(
            !rendered.contains("- Fix bug.\n\n"),
            "trailing newline in summary must not produce a doubled blank line; got:\n{rendered}"
        );
    }

    #[test]
    fn render_section_severity_none_entry_is_rejected() {
        let input = ChangelogInput {
            package: PackageId::parse("my-pkg").unwrap(),
            from: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            to: Some(Version::parse("1.1.0", VersionGrammar::SemVer).unwrap()),
            entries: vec![ChangelogEntry {
                severity: Severity::None,
                source: ChangeSource::Changeset {
                    filename: "bad.md".to_string(),
                    summary: "Should never happen".to_string(),
                },
            }],
        };

        assert!(matches!(render_section(&input), Err(ChangelogError::SeverityNoneEntry)));
    }

    #[test]
    fn render_section_skips_entry_with_empty_summary() {
        let input = ChangelogInput {
            package: PackageId::parse("my-pkg").unwrap(),
            from: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            to: Some(Version::parse("1.1.0", VersionGrammar::SemVer).unwrap()),
            entries: vec![
                ChangelogEntry {
                    severity: Severity::Patch,
                    source: ChangeSource::Changeset {
                        filename: "empty.md".to_string(),
                        summary: "".to_string(),
                    },
                },
                ChangelogEntry {
                    severity: Severity::Patch,
                    source: ChangeSource::Changeset {
                        filename: "real.md".to_string(),
                        summary: "Real change".to_string(),
                    },
                },
            ],
        };

        let rendered = render_section(&input).unwrap();
        assert!(
            !rendered.contains("- \n"),
            "empty summary must not produce a blank bullet; got:\n{rendered}"
        );
        assert!(
            rendered.contains("- Real change"),
            "non-empty entry must still appear; got:\n{rendered}"
        );
    }

    #[test]
    fn render_section_renders_commit_source() {
        let input = ChangelogInput {
            package: PackageId::parse("my-pkg").unwrap(),
            from: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            to: Some(Version::parse("1.1.0", VersionGrammar::SemVer).unwrap()),
            entries: vec![ChangelogEntry {
                severity: Severity::Patch,
                source: ChangeSource::Commit {
                    sha: callisto_model::CommitSha::parse(&"a".repeat(40)).unwrap(),
                    subject: "Fix the thing".to_string(),
                },
            }],
        };

        let rendered = render_section(&input).unwrap();
        assert!(
            rendered.contains("- Fix the thing ("),
            "expected commit subject and short sha, got:\n{rendered}"
        );
    }

    #[test]
    fn render_section_renders_peer_escalation_source() {
        let input = ChangelogInput {
            package: PackageId::parse("my-pkg").unwrap(),
            from: Version::parse("1.0.0", VersionGrammar::SemVer).unwrap(),
            to: Some(Version::parse("1.1.0", VersionGrammar::SemVer).unwrap()),
use std::fs;
use std::path::Path;

use callisto_model::{ApplyPermit, Version};

use crate::changelog::ChangelogError;

/// Prepend a rendered changelog entry for `display_name` to the
/// changelog file at `changelog_path` (relative to `root`).
///
/// # Concurrency
///
/// **Not safe for concurrent calls on the same `path`.** Reads existing
/// content then writes atomically, but a second concurrent call could
/// read stale content between those two points. Callers must ensure
/// sequential access per changelog file -- if this ever moves to
/// parallel `apply`, add a per-path lock before removing this note.
pub fn prepend(
    root: &Path,
    changelog_path: &Path,
    display_name: &str,
    rendered: &str,
    permit: &ApplyPermit,
) -> Result<(), ChangelogError> {
    let full_path = root.join(changelog_path);
    if let Some(parent) = full_path.parent() {
        fs::create_dir_all(parent).map_err(|e| ChangelogError::WriteFailed {
            path: changelog_path.to_path_buf(),
            message: e.to_string(),
        })?;
    }

    let existing = callisto_model::strict_fs::read_optional(&full_path)
        .map_err(|e| ChangelogError::ReadFailed {
            path: changelog_path.to_path_buf(),
            message: e.to_string(),
        })?
        .unwrap_or_else(|| format!("# {display_name}\n\n"));

    // Normalise CRLF → LF so the prefix patterns always match, then restore
    // the original line endings on the way out if the file used CRLF.
    let had_crlf = existing.contains("\r\n");
    let normalised = if had_crlf {
        existing.replace("\r\n", "\n")
    } else {
        existing.clone()
    };

    // Bug 8 guard: if the version heading we are about to insert already exists
    // in the file, skip the write entirely (idempotent behaviour). The heading
    // is the first line of `rendered` (e.g. "## 1.0.0").
    let version_heading = rendered.lines().next().unwrap_or("").trim();
    if !version_heading.is_empty() && normalised.lines().any(|l| l.trim() == version_heading) {
        return Ok(());
    }

    // All three header shapes (blank line after the H1, no blank line, or no
    // matching H1 at all -- e.g. a casing change, HTML anchor, or package
    // rename) splice the new entry in identically; only what counts as
    // "the rest of the file to keep" differs, so compute just that here.
    let rest: &str = if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n\n")) {
        rest
    } else if let Some(rest) = normalised.strip_prefix(&format!("# {display_name}\n")) {
        rest
    } else {
        // No matching H1 found: emit the correct H1 first so the output is
        // well-formed, keeping the entire existing content as the body.
        &normalised
    };

    let mut new_content = String::new();
    new_content.push_str(&format!("# {display_name}\n\n"));
    new_content.push_str(rendered);
    if !rendered.ends_with('\n') {
        new_content.push('\n');
    }
    new_content.push('\n');
    new_content.push_str(rest);

    if had_crlf {
        new_content = new_content.replace('\n', "\r\n");
    }

    callisto_model::atomic::atomic_write(&full_path, &new_content, permit).map_err(|e| ChangelogError::WriteFailed {
        path: changelog_path.to_path_buf(),
        message: e.to_string(),
    })
}

/// The non-empty `## {version}` section body, trimmed.
pub fn extract_section<'a>(changelog: &'a str, version: &Version) -> Option<&'a str> {
    find_section(changelog, version).filter(|section| !section.is_empty())
}

/// The trimmed `## {version}` section body, empty when the heading has no content;
/// `None` only when the heading is absent.
pub fn find_section<'a>(changelog: &'a str, version: &Version) -> Option<&'a str> {
    let target_heading = format!("## {}", version.render());
    let mut start_byte = None;

    let mut offset = 0;
    for line in changelog.split_inclusive('\n') {
        let trimmed = line.trim_end();
        if trimmed == target_heading {
            start_byte = Some(offset + line.len());
            break;
        }
        offset += line.len();
    }

    let start = start_byte?;
    let slice_after = &changelog[start.min(changelog.len())..];

    let mut end = slice_after.len();
    let mut line_offset = 0;

    for line in slice_after.split_inclusive('\n') {
        let trimmed = line.trim_start();
        if line_offset > 0 && (trimmed.starts_with("## ") || trimmed.starts_with("# ")) {
            end = line_offset;
            break;
        }
        line_offset += line.len();
    }

    Some(slice_after[..end.min(slice_after.len())].trim())
}

